      "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">KNOWLEDGE CHECK</text><text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">Sales training and reversion</text><rect x=\"150\" y=\"200\" width=\"800\" height=\"180\" rx=\"20\" fill=\"rgba(239,68,68,0.1)\" stroke=\"#ef4444\" stroke-width=\"2\"/><text x=\"550\" y=\"260\" text-anchor=\"middle\" fill=\"#ef4444\" font-weight=\"bold\" font-size=\"26\">WORST QUARTER</text><text x=\"550\" y=\"310\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Partly real, partly noise</text><text x=\"550\" y=\"350\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Reversion already coming</text><rect x=\"150\" y=\"430\" width=\"800\" height=\"180\" rx=\"20\" fill=\"rgba(16,185,129,0.1)\" stroke=\"#10b981\" stroke-width=\"2\"/><text x=\"550\" y=\"490\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"26\">NEEDED: CONTROL GROUP</text><text x=\"550\" y=\"540\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Similar teams without the training</text><text x=\"550\" y=\"580\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Compare reversion magnitudes</text></svg>",
