"/><text x=\"200\" y=\"605\" text-anchor=\"start\" fill=\"#f59e0b\" font-weight=\"bold\" font-size=\"22\">5.</text><text x=\"290\" y=\"605\" text-anchor=\"start\" fill=\"#fff\" font-size=\"22\">EXPECTED OUTCOME + PROBABILITY</text><text x=\"290\" y=\"645\" text-anchor=\"start\" fill=\"#888\" font-size=\"18\">\"__ by [date], __% confident\" + worst case</text><rect x=\"150\" y=\"690\" width=\"800\" height=\"110\" rx=\"16\" fill=\"rgba(236,72,153,0.12)\" stroke=\"#ec4899\" stroke-width=\"2\"/><text x=\"200\" y=\"735\" text-anchor=\"start\" fill=\"#ec4899\" font-weight=\"bold\" font-size=\"22\">6.</text><text x=\"290\" y=\"735\" text-anchor=\"start\" fill=\"#fff\" font-size=\"22\">EMOTIONAL STATE — ONE HONEST LINE</text><text x=\"290\" y=\"775\" text-anchor=\"start\" fill=\"#888\" font-size=\"18\">Tired, rushed, excited, pressured?</text><rect x=\"150\" y=\"820\" width=\"800\" height=\"110\" rx=\"16\" fill=\"rgba(20,184,166,0.12)\" stroke=\"#10b981\" stroke-width=\"2\"/><text x=\"200\" y=\"865\" text-anchor=\"start\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"22\">7.</text><text x=\"290\" y=\"865\" text-anchor=\"start\" fill=\"#fff\" font-size=\"22\">REVIEW DATE — IN THE CALENDAR NOW</text><text x=\"290\" y=\"905\" text-anchor=\"start\" fill=\"#888\" font-size=\"18\">Grade the process, not the luck</text></svg>",
      "caption": "Five entries in, you'll catch yourself mid-bias — that's the payoff"
