" stroke-width=\"2\"/><text x=\"550\" y=\"865\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"24\">LAST ASSIGNMENT</text><text x=\"550\" y=\"920\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Run one pre-mortem this week</text></svg>",
